// The only place the interface talks to the engine.
//
// Every call goes through here, typed against the bindings generated from the shell's wire
// types (`src/lib/bindings/`, regenerated by `npm run bindings`). Nothing else in the
// interface imports `invoke`, so the whole surface is one file to read.

import { invoke } from "@tauri-apps/api/core";

import type { Document } from "./bindings/Document";
import type { EngineError } from "./bindings/EngineError";
import type { LibraryStatus } from "./bindings/LibraryStatus";
import type { SearchHit } from "./bindings/SearchHit";
import type { Topic } from "./bindings/Topic";

export type { Document, EngineError, LibraryStatus, SearchHit, Topic };

/** The opaque token carried between a read and a write. Never inspected. */
export type Revision = Document["revision"];

/** The error causes from `backend-contract.md`. */
export type ErrorKind = EngineError["kind"];

/** A failure the interface can branch on, rather than a string to show raw. */
export class EngineFailure extends Error {
  readonly kind: ErrorKind;

  constructor(error: EngineError) {
    super(error.message);
    this.name = "EngineFailure";
    this.kind = error.kind;
  }
}

function looksLikeEngineError(value: unknown): value is EngineError {
  return (
    typeof value === "object" &&
    value !== null &&
    "kind" in value &&
    "message" in value &&
    typeof (value as EngineError).kind === "string"
  );
}

async function call<T>(command: string, args?: Record<string, unknown>): Promise<T> {
  try {
    return await invoke<T>(command, args);
  } catch (thrown) {
    // The shell returns a structured failure; anything else is a bug in the bridge and is
    // reported as such rather than being flattened into the same shape.
    if (looksLikeEngineError(thrown)) throw new EngineFailure(thrown);
    throw new EngineFailure({
      kind: "LibraryError",
      message: `unexpected failure from ${command}: ${String(thrown)}`,
    });
  }
}

export const engine = {
  library: {
    create: (path: string, name: string) =>
      call<LibraryStatus>("library_create", { path, name }),
    open: (path: string) => call<LibraryStatus>("library_open", { path }),
    close: () => call<void>("library_close"),
    status: () => call<LibraryStatus>("library_status"),
    rebuildIndex: () => call<LibraryStatus>("library_rebuild_index"),
  },
  topic: {
    tree: () => call<Topic[]>("topic_tree"),
    create: (parent: string | null, name: string) =>
      call<string>("topic_create", { parent, name }),
    rename: (topic: string, name: string) =>
      call<void>("topic_rename", { topic, name }),
  },
  document: {
    create: (topic: string, title: string) =>
      call<string>("document_create", { topic, title }),
    read: (document: string) => call<Document>("document_read", { document }),
    write: (document: string, body: string, revision: Revision) =>
      call<Document>("document_write", { document, body, revision }),
    rename: (document: string, title: string) =>
      call<Document>("document_rename", { document, title }),
    delete: (document: string) => call<void>("document_delete", { document }),
  },
  search: (query: string) => call<SearchHit[]>("search", { query }),
};
